+package com.example.itemtracker;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.applayout.AppLayout;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.H2;
+import com.vaadin.flow.component.html.ListItem;
+import com.vaadin.flow.component.html.Span;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadinbench.Application;
+import com.vaadinbench.items.ItemsView;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(classes = Application.class)
+class ItemsViewTest extends SpringBrowserlessTest {
+
+    @Test
+    void addAppendsItemsAndClearsField() {
+        navigate(ItemsView.class);
+        assertEquals("Items: 0", $(Span.class).withText("Items: 0").single().getText());
+
+        $(TextField.class).single().setValue("first");
+        $(Button.class).withText("Add").single().click();
+        $(TextField.class).single().setValue("second");
+        $(Button.class).withText("Add").single().click();
+        $(TextField.class).single().setValue("second");
+        $(Button.class).withText("Add").single().click();
+
+        assertEquals(3, $(ListItem.class).all().size());
+        assertEquals("first", $(ListItem.class).all().get(0).getText());
+        assertEquals("second", $(ListItem.class).all().get(2).getText());
+        assertEquals("", $(TextField.class).single().getValue());
+        assertEquals("Items: 3", $(Span.class).withText("Items: 3").single().getText());
+    }
+
+    @Test
+    void blankAddAddsNothingAndMarksFieldInvalid() {
+        navigate(ItemsView.class);
+        $(TextField.class).single().setValue("   ");
+        $(Button.class).withText("Add").single().click();
+
+        assertEquals(0, $(ListItem.class).all().size());
+        assertEquals("Items: 0", $(Span.class).withText("Items: 0").single().getText());
+        assertTrue($(TextField.class).single().isInvalid());
+    }
+
+    @Test
+    void clearRemovesAllItems() {
+        navigate(ItemsView.class);
+        $(TextField.class).single().setValue("one");
+        $(Button.class).withText("Add").single().click();
+        $(Button.class).withText("Clear").single().click();
+
+        assertEquals(0, $(ListItem.class).all().size());
+        assertEquals("Items: 0", $(Span.class).withText("Items: 0").single().getText());
+        assertEquals("Items", $(H1.class).single().getText());
+    }
+
+    @Test
+    void shellAndControlsAreAvailable() {
+        navigate(ItemsView.class);
+        assertEquals(1, $(AppLayout.class).all().size());
+        assertEquals("Item Tracker", $(H2.class).single().getText());
+        assertEquals("Item", $(TextField.class).single().getLabel());
+        assertTrue($(Button.class).withText("Add").single().isEnabled());
+        assertTrue($(Button.class).withText("Clear").single().isEnabled());
+        assertFalse($(TextField.class).single().isInvalid());
+    }
+
+}
